from collections import deque
class Solution:
    def minThreshold(self, n, edges, source, target, k):
        cands = [0] + sorted({w for _, _, w in edges})
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))
        def ok(T):
            dist = [-1] * n
            dq = deque([source])
            dist[source] = 0
            while dq:
                u = dq.popleft()
                if u == target:
                    return dist[u] <= k
                for v, w in adj[u]:
                    c = 0 if w <= T else 1
                    nd = dist[u] + c
                    if dist[v] == -1 or nd < dist[v]:
                        dist[v] = nd
                        if c == 0:
                            dq.appendleft(v)
                        else:
                            dq.append(v)
            return False
        for T in cands:
            if ok(T):
                return T
        return -1

