import java.util.*;
class Solution {
    public int minThreshold(int n, int[][] edges, int source, int target, int k) {
        TreeSet<Integer> cands = new TreeSet<>(); cands.add(0);
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
            cands.add(e[2]);
        }
        for (int T : cands) {
            if (ok(n, adj, source, target, k, T)) return T;
        }
        return -1;
    }
    private boolean ok(int n, List<int[]>[] adj, int src, int tgt, int k, int T) {
        int[] dist = new int[n]; Arrays.fill(dist, Integer.MAX_VALUE);
        Deque<Integer> dq = new ArrayDeque<>(); dq.add(src); dist[src] = 0;
        while (!dq.isEmpty()) {
            int u = dq.poll();
            if (u == tgt) return dist[u] <= k;
            for (int[] e : adj[u]) {
                int c = e[1] <= T ? 0 : 1, nd = dist[u] + c;
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    if (c == 0) dq.addFirst(e[0]); else dq.addLast(e[0]);
                }
            }
        }
        return false;
    }
}

