        Deque<Integer> dq = new ArrayDeque<>(); dq.add(src); dist[src] = 0;
        while (!dq.isEmpty()) {
            int u = dq.poll();
            if (u == tgt) return dist[u] <= k;
            for (int[] e : adj[u]) {
                int c = e[1] <= T ? 0 : 1, nd = dist[u] + c;
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    if (c == 0) dq.addFirst(e[0]); else dq.addLast(e[0]);
                }
            }
        }
        return false;
    }
    public int minThreshold(int n, int[][] edges, int source, int target, int k) {
        TreeSet<Long> s = new TreeSet<>(); s.add(0L);
